/// The option keys of the twelve `ConfigOptionFloats` that
/// `AutoContourHolesCompensationParams(const PrintConfig&)` reads (Print.hpp:371-385), in the order of
/// PrintConfig.hpp:1747-1758. The front end hands these the whole JSON array joined with ',' as the
/// pin's `ConfigBase::load_from_json` does (Config.cpp:1030-1100).
pub const CIRCLE_COMPENSATION_FLOATS_KEYS: [&str; 12] = [
    "circle_compensation_speed",
    "diameter_limit",
    "counter_coef_1",
    "counter_coef_2",
    "counter_coef_3",
    "hole_coef_1",
    "hole_coef_2",
    "hole_coef_3",
    "counter_limit_min",
    "counter_limit_max",
    "hole_limit_min",
    "hole_limit_max",
];

impl PrintConfig {
    /// PrintConfig.hpp:1312-1342, Config.hpp:918-939. Keep all configured limits while
    /// maintaining the normal-mode scalar used by existing callers.
    fn set_machine_limit_rows(&mut self, key: &str, value: &str) -> bool {
        use crate::config::{ConfigOption, ConfigOptionFloatsNullable};
        let scalar = match key {
            "machine_max_acceleration_x" => &mut self.machine_max_acceleration_x,
            "machine_max_acceleration_y" => &mut self.machine_max_acceleration_y,
            "machine_max_acceleration_z" => &mut self.machine_max_acceleration_z,
            "machine_max_acceleration_e" => &mut self.machine_max_acceleration_e,
            "machine_max_speed_x" => &mut self.machine_max_speed_x,
            "machine_max_speed_y" => &mut self.machine_max_speed_y,
            "machine_max_speed_z" => &mut self.machine_max_speed_z,
            "machine_max_speed_e" => &mut self.machine_max_speed_e,
            "machine_max_jerk_x" => &mut self.machine_max_jerk_x,
            "machine_max_jerk_y" => &mut self.machine_max_jerk_y,
            "machine_max_jerk_z" => &mut self.machine_max_jerk_z,
            "machine_max_jerk_e" => &mut self.machine_max_jerk_e,
            "machine_max_acceleration_extruding" => &mut self.machine_max_acceleration_extruding,
            "machine_max_acceleration_retracting" => &mut self.machine_max_acceleration_retracting,
            "machine_max_acceleration_travel" => &mut self.machine_max_acceleration_travel,
            "machine_min_extruding_rate" => &mut self.machine_min_extruding_rate,
            "machine_min_travel_rate" => &mut self.machine_min_travel_rate,
            _ => return false,
        };
        let mut option = ConfigOptionFloatsNullable::new();
        if matches!(option.deserialize(value, false), Ok(true)) {
            if let Some(&first) = option.values.first().filter(|v| !v.is_nan()) {
                *scalar = first;
            }
            let rows = option.values.into_iter().map(|v| (!v.is_nan()).then_some(v)).collect();
            self.machine_axis_limit_rows.insert(key.to_owned(), rows);
        }
        true
    }

    /// GCodeProcessor.cpp:115-119, 2030-2036. Convert to planner precision.
    pub(crate) fn machine_limit_values(&self, key: &str, scalar: CoordF) -> Vec<f32> {
        if machine_limit_rows_enabled(key) {
            if let Some(rows) = self.machine_axis_limit_rows.get(key) {
                let mut values: Vec<f32> = rows.iter().map(|v| v.unwrap_or(f64::NAN) as f32).collect();
                // A caller may edit the public scalar after loading this profile.
                if matches!(rows.first(), Some(Some(_))) {
                    values[0] = scalar as f32;
                }
                return values;
            }
        }
        vec![scalar as f32; 2]
    }

    /// The typed field of one of [`CIRCLE_COMPENSATION_FLOATS_KEYS`].
    pub fn circle_compensation_floats_mut(&mut self, key: &str) -> Option<&mut Vec<f64>> {
        Some(match key {
            "circle_compensation_speed" => &mut self.circle_compensation_speed,
            "diameter_limit" => &mut self.diameter_limit,
            "counter_coef_1" => &mut self.counter_coef_1,
            "counter_coef_2" => &mut self.counter_coef_2,
            "counter_coef_3" => &mut self.counter_coef_3,
            "hole_coef_1" => &mut self.hole_coef_1,
            "hole_coef_2" => &mut self.hole_coef_2,
            "hole_coef_3" => &mut self.hole_coef_3,
            "counter_limit_min" => &mut self.counter_limit_min,
            "counter_limit_max" => &mut self.counter_limit_max,
            "hole_limit_min" => &mut self.hole_limit_min,
            "hole_limit_max" => &mut self.hole_limit_max,
            _ => return None,
        })
    }

    /// The `values` of one of [`CIRCLE_COMPENSATION_FLOATS_KEYS`] (empty for any other key), the shape
    /// `AutoContourHolesCompensationParams::new_from_config_values` takes.
    pub fn circle_compensation_floats(&self, key: &str) -> Vec<f64> {
        match key {
            "circle_compensation_speed" => self.circle_compensation_speed.clone(),
            "diameter_limit" => self.diameter_limit.clone(),
            "counter_coef_1" => self.counter_coef_1.clone(),
            "counter_coef_2" => self.counter_coef_2.clone(),
            "counter_coef_3" => self.counter_coef_3.clone(),
            "hole_coef_1" => self.hole_coef_1.clone(),
            "hole_coef_2" => self.hole_coef_2.clone(),
            "hole_coef_3" => self.hole_coef_3.clone(),
            "counter_limit_min" => self.counter_limit_min.clone(),
            "counter_limit_max" => self.counter_limit_max.clone(),
            "hole_limit_min" => self.hole_limit_min.clone(),
            "hole_limit_max" => self.hole_limit_max.clone(),
            _ => Vec::new(),
        }
    }

    /// `ConfigOptionFloats::deserialize(str)` (Config.hpp:918-939) into one of
    /// [`CIRCLE_COMPENSATION_FLOATS_KEYS`]: the comma-separated list replaces the values. On a
    /// failed deserialize (a `nil` item: the options are not nullable) the field keeps its values, as
    /// `ConfigBase::set_deserialize_raw` leaves the option when it throws. Returns false for any other key.
    pub fn set_deserialize_circle_compensation_floats(&mut self, key: &str, value: &str) -> bool {
        use crate::config::ConfigOption as _;
        let Some(field) = self.circle_compensation_floats_mut(key) else {
            return false;
        };
        let mut opt = crate::config::ConfigOptionFloats::new();
        if matches!(opt.deserialize(value, false), Ok(true)) {
            *field = opt.values;
        }
        true
    }

    /// `filament_velocity_adaptation_factor.get_at(idx)` (Config.hpp:681-685: the value at `idx`, the
    /// first value past the end). GCode.cpp:6779/6809 read it at
    /// `get_filament_config_index(m_writer.filament()->id())` (GCode.cpp:1570). An empty vector (the pin
    /// asserts it is not) gives the option's default 1.0.
    pub fn filament_velocity_adaptation_factor_at(&self, idx: usize) -> f64 {
        let values = &self.filament_velocity_adaptation_factor;
        if values.is_empty() {
            return 1.0;
        }
        if idx < values.len() {
            values[idx]
        } else {
            values[0]
        }
    }

    /// `ConfigOptionFloats::deserialize(str)` (Config.hpp:918-939) into
    /// `filament_velocity_adaptation_factor` (PrintConfig.hpp:1745): the comma-separated list replaces
    /// the values; on a failed deserialize (a `nil` item: the option is not nullable) the field keeps its
    /// values, as `ConfigBase::set_deserialize_raw` leaves the option when it throws.
    pub fn set_deserialize_filament_velocity_adaptation_factor(&mut self, value: &str) -> bool {
        use crate::config::ConfigOption as _;
        let mut opt = crate::config::ConfigOptionFloats::new();
        if matches!(opt.deserialize(value, false), Ok(true)) {
            self.filament_velocity_adaptation_factor = opt.values;
        }
        true
    }

    /// `cast<ExtruderType>(config.extruder_type.values)` (GCodeProcessor.cpp:2040; Config.hpp `cast`
    /// is a `static_cast` of each value): the typed `extruder_type` as `m_result.extruder_types`.
    pub fn extruder_types(&self) -> Vec<crate::extruder::ExtruderType> {
        self.extruder_type.iter().map(|v| crate::extruder::ExtruderType::from_i32(*v)).collect()
    }

    /// `ConfigOptionInts::deserialize(str)` (Config.hpp, ConfigOptionIntsTempl::deserialize) into
    /// `printer_extruder_id` (PrintConfig.hpp:1536); a failed deserialize keeps the values, as
    /// [`PrintConfig::set_deserialize_filament_velocity_adaptation_factor`] does.
    pub fn set_deserialize_printer_extruder_id(&mut self, value: &str) -> bool {
        use crate::config::ConfigOption as _;
        let mut opt = crate::config::ConfigOptionInts::new();
        if matches!(opt.deserialize(value, false), Ok(true)) {
            self.printer_extruder_id = opt.values;
        }
        true
    }

    /// `ConfigOptionStrings::deserialize(str)` (Config.hpp:1191-1196, `unescape_strings_cstyle`) into
    /// `printer_extruder_variant` (PrintConfig.hpp:1538). A JSON array reaches it as
    /// ConfigBase::load_from_json builds it for a coStrings option: each item quoted with
    /// `escape_string_cstyle`, joined with ';' (Config.cpp:922-934, 1061-1063).
    pub fn set_deserialize_printer_extruder_variant(&mut self, value: &str) -> bool {
        use crate::config::ConfigOption as _;
        let mut opt = crate::config::ConfigOptionStrings::new();
        if matches!(opt.deserialize(value, false), Ok(true)) {
            self.printer_extruder_variant = opt.values;
        }
        true
    }

    /// `ConfigOptionEnumsGeneric::deserialize(str)` (Config.hpp:2185-2207) with the ExtruderType keys
    /// map (PrintConfig.cpp:891-895) into `extruder_type` (PrintConfig.hpp:1519). A key the map does
    /// not know fails the deserialize; ConfigBase::set_deserialize_raw then substitutes the option's
    /// default for a coEnums option (Config.cpp:692-705: `opt->set(optdef->default_value)`, here
    /// {etDirectDrive}). A `nil` item (not nullable) throws, and the field keeps its values.
    pub fn set_deserialize_extruder_type(&mut self, value: &str) -> bool {
        use crate::config::ConfigOption as _;
        let keys_map: &'static crate::config::t_config_enum_values = &*enums::s_keys_map_ExtruderType;
        let mut opt = crate::config::ConfigOptionEnumsGeneric::new(Some(keys_map));
        match opt.deserialize(value, false) {
            Ok(true) => self.extruder_type = opt.values,
            Ok(false) => self.extruder_type = vec![crate::extruder::ExtruderType::EtDirectDrive as i32],
            Err(_) => {}
        }
        true
    }
}

/// Per-extruder cooling configuration.
/// Mirrors all fields from the C++ EXTRUDER_CONFIG macro block
/// (GCodeEditor.cpp:393-460).
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct PerExtruderCoolingConfig {
    /// Minimum fan speed (0-100).
    pub fan_min_speed: i32,
    /// Maximum fan speed (0-100).
    pub fan_max_speed: i32,
    /// Enable slow down for layer cooling.
    pub slow_down_for_layer_cooling: bool,
    /// Minimum layer time for slowdown (seconds).
    pub slow_down_layer_time: f32,
    /// Minimum print speed when slowing (mm/s).
    pub slow_down_min_speed: f32,
    /// Fan cooling layer time threshold (seconds). Below slow_down_layer_time => max fan.
    /// Between slow_down_layer_time and fan_cooling_layer_time => interpolated fan.
    pub fan_cooling_layer_time: f32,
    /// Disable fan for first N layers.
    pub close_fan_the_first_x_layers: i32,
    /// Layer at which fan reaches full speed (for ramp). 0 = disabled.
    pub full_fan_speed_layer: i32,
    /// Overhang fan speed (0-100).
    pub overhang_fan_speed: i32,
    /// If true, fan starts at fan_min_speed instead of 0 to reduce start/stop freq.
    pub reduce_fan_stop_start_freq: bool,
    /// Additional (auxiliary) cooling fan speed (0-100).
    pub additional_cooling_fan_speed: i32,
    /// Fan speed for first X layers (0-100).
    pub first_x_layer_fan_speed: i32,
    /// Pre-start time for overhang fan (seconds). Look ahead this many seconds.
    pub pre_start_fan_time: f32,
    /// Don't slow down external perimeters (outer walls) for cooling.
    pub no_slow_down_for_cooling_on_outwalls: bool,
    /// Cooling slowdown logic: 0 = UniformCooling, 1 = ConsistentSurface.
    pub cooling_slowdown_logic: i32,
    /// Perimeter transition distance for ConsistentSurface (mm).
    pub cooling_perimeter_transition_distance: f32,
}

impl Default for PerExtruderCoolingConfig {
    fn default() -> Self {
        Self {
            fan_min_speed: 100,
            fan_max_speed: 100,
            slow_down_for_layer_cooling: true,
            slow_down_layer_time: 4.0,
            slow_down_min_speed: 20.0,
            fan_cooling_layer_time: 100.0,
            close_fan_the_first_x_layers: 1,
            full_fan_speed_layer: 0,
            overhang_fan_speed: 100,
            reduce_fan_stop_start_freq: false,
            additional_cooling_fan_speed: 0,
            first_x_layer_fan_speed: 0,
            pre_start_fan_time: 0.0,
            no_slow_down_for_cooling_on_outwalls: false,
            cooling_slowdown_logic: 0,
            cooling_perimeter_transition_distance: 5.0,
        }
    }
}

impl PrintConfig {
    // Create a new PrintConfig with default values.
    pub fn new() -> Self {
        Self::default()
    }

    /// Number of configured filaments/extruder slots.
    ///
    /// C++ derives this from the per-filament vector lengths
    /// (`filament_diameter.size()`, PrintConfig.hpp). The Rust config's
    /// per-filament vectors are empty for single-material configs (scalar
    /// fields = filament 0), so empty ⇒ 1.
    pub fn num_filaments(&self) -> usize {
        self.filament_diameters
            .len()
            .max(self.filament_colours.len())
            .max(1)
    }

    /// Apply all settings from another config, overwriting this one.
    /// Port of C++ DynamicPrintConfig::apply().
    pub fn apply_from(&mut self, other: &PrintConfig) {
        *self = other.clone();
    }

    /// Builder method: set layer height.
    pub fn layer_height(mut self, height: CoordF) -> Self {
        self.layer_height = height;
        self
    }

    /// Builder method: set first layer height.
    pub fn first_layer_height(mut self, height: CoordF) -> Self {
        self.first_layer_height = height;
        self
    }

    /// Builder method: set nozzle diameter.
    pub fn nozzle_diameter(mut self, diameter: CoordF) -> Self {
        self.nozzle_diameter = diameter;
        self
    }

    /// Builder method: set print speed.
    pub fn print_speed(mut self, speed: CoordF) -> Self {
        self.print_speed = speed;
        self
    }

    /// Builder method: enable/disable support.
    pub fn support(mut self, enabled: bool) -> Self {
        self.support_enabled = enabled;
        self
    }

    /// Builder method: set support type.
    pub fn support_type(mut self, support_type: SupportType) -> Self {
        self.support_type = support_type;
        self
    }

    /// Builder method: set brim width.
    pub fn brim_width(mut self, width: CoordF) -> Self {
        self.brim_width = width;
        self
    }

    /// Builder method: enable or disable raft.
    pub fn raft_enabled(mut self, enabled: bool) -> Self {
        self.raft_enabled = enabled;
        self
    }

    /// Builder method: set raft layers.
    pub fn raft_layers(mut self, layers: u32) -> Self {
        self.raft_layers = layers;
        if layers > 0 {
            self.raft_enabled = true;
        }
        self
    }

    /// Builder method: set raft expansion.
    pub fn raft_expansion(mut self, expansion: CoordF) -> Self {
        self.raft_expansion = expansion.max(0.0);
        self
    }

    /// Builder method: set raft contact distance.
    pub fn raft_contact_distance(mut self, distance: CoordF) -> Self {
        self.raft_contact_distance = distance.max(0.0);
        self
    }

    /// Builder method: set raft density.
    pub fn raft_density(mut self, density: CoordF) -> Self {
        self.raft_density = density.clamp(0.0, 1.0);
        self
    }

    /// Validate the configuration with min/max bounds from C++ PrintConfig.
    // PrintConfig.cpp:8977  std::map<std::string,std::string> validate(const FullPrintConfig &cfg, bool under_cli)
    // FIDELITY-NOTE: the C++ free `validate` operates on a FullPrintConfig / DynamicConfig
    // (ConfigOptionDef registry, get_abs_value, serialize, per-extruder *vectors*, has_enum_value)
    // none of which exist in this scalar struct model. The thresholds for the fields that DO
    // map 1:1 are mirrored here exactly; the original signature (Result<(),String> returning the
    // first error rather than a key->message map) is preserved because there is no
    // DynamicConfig/error-map model in this crate. The vector-valued C++ checks collapse to a
    // single scalar check (one nozzle / one filament).
    pub fn validate(&self) -> Result<(), String> {
        // PrintConfig.cpp:8981  --layer-height: <= 0 invalid
        if self.layer_height <= 0.0 {
            return Err(format!("invalid value {}", self.layer_height));
        }
        // PrintConfig.cpp:8984  else if (fabs(fmod(layer_height, SCALING_FACTOR)) > 1e-4) invalid
        else if (self.layer_height % crate::libslic3r::SCALING_FACTOR).abs() > 1e-4 {
            return Err(format!("invalid value {}", self.layer_height));
        }
        // PrintConfig.cpp:8989  --first-layer-height: initial_layer_print_height <= 0 invalid
        if self.first_layer_height <= 0.0 {
            return Err(format!("invalid value {}", self.first_layer_height));
        }
        // PrintConfig.cpp:8994  --filament-diameter: fd < 1 invalid
        if self.filament_diameter < 1.0 {
            return Err(format!("invalid value {}", self.filament_diameter));
        }
        // PrintConfig.cpp:9001  --nozzle-diameter: nd < 0.005 invalid
        if self.nozzle_diameter < 0.005 {
            return Err(format!("invalid value {}", self.nozzle_diameter));
        }
        // PrintConfig.cpp:9080  extruder clearance: <= 0 invalid
        if self.extruder_clearance_max_radius <= 0.0 {
            return Err(format!("invalid value {}", self.extruder_clearance_max_radius));
        }
        // PrintConfig.cpp:9083
        if self.extruder_clearance_height_to_rod <= 0.0 {
            return Err(format!("invalid value {}", self.extruder_clearance_height_to_rod));
        }
        // PrintConfig.cpp:9086
        if self.extruder_clearance_height_to_lid <= 0.0 {
            return Err(format!("invalid value {}", self.extruder_clearance_height_to_lid));
        }
        // PrintConfig.cpp:9093  --extrusion-multiplier: filament_flow_ratio em <= 0 invalid
        if self.filament_flow_ratio <= 0.0 {
            return Err(format!("invalid value {}", self.filament_flow_ratio));
        }
        Ok(())
    }
}

impl PrintConfig {
    // Builder: set relative extrusion mode (M83).
    pub fn use_relative_e(mut self, relative: bool) -> Self {
        self.use_relative_e = relative;
        self
    }

    pub fn arc_fitting(mut self, enabled: bool) -> Self {
        self.arc_fitting_enabled = enabled;
        self
    }

    pub fn arc_fitting_tolerance(mut self, tolerance: CoordF) -> Self {
        self.arc_fitting_tolerance = tolerance;
        self
    }

    pub fn arc_fitting_radius(mut self, min: CoordF, max: CoordF) -> Self {
        self.arc_fitting_min_radius = min;
        self.arc_fitting_max_radius = max;
        self
    }

    /// Enable or disable avoid crossing perimeters.
    pub fn avoid_crossing_perimeters(mut self, enabled: bool) -> Self {
        self.avoid_crossing_perimeters = enabled;
        self
    }

    /// Set the maximum detour percentage for avoid crossing perimeters.
    pub fn avoid_crossing_max_detour(mut self, percent: CoordF) -> Self {
        self.avoid_crossing_max_detour = percent;
        self
    }
}

