// === Parse helpers for BambuStudio JSON values (all stored as strings) ===

pub fn parse_f64(s: &str) -> Option<f64> {
    // NOTE (R345): per-extruder configs arrive as comma-arrays
    // ("105,105,105,105,105"); this plain parse fails on the comma, so the typed
    // field silently keeps its struct default. This is a real config-load bug
    // (e.g. initial_layer_infill_speed stays 50 instead of the profile's 105),
    // but a gated first-element fix was measured BYTE-NEUTRAL: the affected
    // first-layer-infill lines diverge geometrically (cascade), so correcting
    // the speed value does not align them. Left as-is; revisit if the underlying
    // geometry is ever brought to parity.
    s.trim_end_matches('%').parse::<f64>().ok()
}

/// R706 — parse a BambuStudio `coPercent` option as its PERCENT NUMBER.
///
/// `min_bead_width` / `min_feature_size` / `wall_transition_length` /
/// `wall_transition_filter_deviation` are all `coPercent` in C++
/// (PrintConfig.cpp:5940-6010) and their consumer multiplies by
/// `0.01 * min_nozzle_diameter` (PerimeterGenerator.cpp:1540-1549), which our
/// `perimeter_generator.rs:3238-3250` mirrors. So the stored value must be the
/// PERCENT (85), not a fraction (0.85) and not millimetres (0.34).
///
/// Accepts `"85%"` and `"85"` alike, both -> 85.0. Contrast [`parse_pct`], which
/// returns a FRACTION (0.85) — feeding that to the percent consumer under-scales
/// by 100x, and feeding millimetres under-scales by ~250-850x (R706).
pub fn parse_percent_number(s: &str) -> Option<f64> {
    s.trim().trim_end_matches('%').trim().parse::<f64>().ok()
}

pub fn parse_pct(s: &str) -> Option<f64> {
    if s.ends_with('%') {
        s.trim_end_matches('%')
            .parse::<f64>()
            .ok()
            .map(|v| v / 100.0)
    } else {
        s.parse::<f64>().ok()
    }
}

pub fn parse_bool(s: &str) -> Option<bool> {
    Some(s == "1" || s.eq_ignore_ascii_case("true"))
}

pub fn parse_u32(s: &str) -> Option<u32> {
    s.parse::<u32>().ok()
}

pub fn parse_i32(s: &str) -> Option<i32> {
    s.parse::<i32>().ok()
}

/// Parse a C++ ConfigOptionFloatOrPercent string ("10" -> 10 mm, "10%" -> 10 percent).
pub fn parse_float_or_percent(s: &str) -> Option<crate::config::FloatOrPercent> {
    let trimmed = s.trim();
    if let Some(stripped) = trimmed.strip_suffix('%') {
        stripped
            .parse::<f64>()
            .ok()
            .map(|v| crate::config::FloatOrPercent::with(v, true))
    } else {
        trimmed
            .parse::<f64>()
            .ok()
            .map(|v| crate::config::FloatOrPercent::with(v, false))
    }
}

impl PrintConfig {
    /// Apply a key-value pair from BambuStudio project_settings JSON.
    /// Returns true if the key was recognized and applied.
    pub fn set_deserialize(&mut self, key: &str, value: &str) -> bool {
        if profile_machine_limit_rows_enabled(key) && self.set_machine_limit_rows(key, value) {
            return true;
        }
        match key {
            // PrintConfig.hpp:1747-1758: the twelve ConfigOptionFloats of the auto circle compensation,
            // deserialized as the pin's ConfigOptionFloats (Config.hpp:918-939).
            k if CIRCLE_COMPENSATION_FLOATS_KEYS.contains(&k) => {
                self.set_deserialize_circle_compensation_floats(k, value)
            }
            // PrintConfig.hpp:1745 (ConfigOptionFloats, Config.hpp:918-939).
            "filament_velocity_adaptation_factor" => {
                self.set_deserialize_filament_velocity_adaptation_factor(value)
            }
            // PrintConfig.hpp:1536, 1538, 1519 (GCodeProcessor.cpp:2038-2040).
            "printer_extruder_id" => self.set_deserialize_printer_extruder_id(value),
            "printer_extruder_variant" => self.set_deserialize_printer_extruder_variant(value),
            "extruder_type" => self.set_deserialize_extruder_type(value),
            // === Layer Heights ===
            "layer_height" => {
                if let Some(v) = parse_f64(value) {
                    self.layer_height = v;
                }
                true
            }
            "initial_layer_print_height" => {
                if let Some(v) = parse_f64(value) {
                    self.first_layer_height = v;
                }
                true
            }

            // === Speeds ===
            "outer_wall_speed" => {
                if let Some(v) = parse_f64(value) {
                    self.print_speed = v;
                }
                true
            }
            "travel_speed" => {
                if let Some(v) = parse_f64(value) {
                    self.travel_speed = v;
                }
                true
            }
            "initial_layer_speed" => {
                if let Some(v) = parse_f64(value) {
                    self.first_layer_speed = v;
                }
                true
            }

            // === Temperatures ===
            "nozzle_temperature" => {
                if let Some(v) = parse_f64(value) {
                    self.extruder_temperature = v as u32;
                }
                true
            }
            "nozzle_temperature_initial_layer" => {
                if let Some(v) = parse_f64(value) {
                    self.first_layer_extruder_temperature = v as u32;
                }
                true
            }
            "nozzle_temperature_range_high" => {
                if let Some(v) = parse_f64(value) {
                    self.nozzle_temperature_range_high = v as u32;
                }
                true
            }
            // Custom tool-change template (GCode.cpp:754). Consumed by the
            // wipe-tower export, which substitutes the evaluated block for the
            // tower's `[change_filament_gcode]` placeholder.
            "change_filament_gcode" => {
                self.change_filament_gcode = value.to_string();
                true
            }
            // Per-filament start/end templates. append_tcr (GCode.cpp:1035-1053)
            // substitutes these into the tower's `[filament_start_gcode]` /
            // `[filament_end_gcode]` placeholders (WipeTower.cpp:2465/2483)
            // alongside the change-filament block. Both keys existed only in
            // `apply_key_value`, never in `set_deserialize`, so the load path
            // left them empty and Majora was missing 2,723 of each block (R495).
            "filament_start_gcode" => {
                self.filament_start_gcode = value.to_string();
                true
            }
            "filament_end_gcode" => {
                self.filament_end_gcode = value.to_string();
                true
            }

            // === Retraction ===
            "retraction_length" => {
                if let Some(v) = parse_f64(value) {
                    self.retract_length = v;
                }
                true
            }
            "retraction_speed" => {
                if let Some(v) = parse_f64(value) {
                    self.retract_speed = v;
                }
                true
            }
            "z_hop" => {
                if let Some(v) = parse_f64(value) {
                    self.retract_lift = v;
                }
                true
            }
            "retract_when_changing_layer" => {
                if let Some(v) = parse_f64(value) {
                    self.retract_before_travel = v;
                }
                true
            }
            "deretraction_speed" => {
                if let Some(v) = parse_f64(value) {
                    self.deretract_speed = v;
                }
                true
            }
            "retract_length_toolchange" => {
                if let Some(v) = parse_f64(value) {
                    self.retract_length_toolchange = v;
                }
                true
            }
            "retract_before_wipe" => {
                if let Some(v) = parse_pct(value) {
                    self.retract_before_wipe = v;
                }
                true
            }

            // === Filament ===
            "filament_density" => {
                if let Some(v) = parse_f64(value) {
                    self.filament_density = v;
                }
                true
            }
            "filament_cost" => {
                if let Some(v) = parse_f64(value) {
                    self.filament_cost = v;
                }
                true
            }
            "filament_flow_ratio" => {
                if let Some(v) = parse_f64(value) {
                    self.filament_flow_ratio = v;
                }
                true
            }
            // Per-filament nullable overrides (PrintConfig.cpp:82-90); the
            // loader passes the first element of the per-filament JSON array.
            "filament_enable_overhang_speed" => {
                if let Some(v) = parse_bool(value) {
                    self.filament_enable_overhang_speed = v;
                }
                true
            }
            "filament_bridge_speed" => {
                if let Some(v) = parse_f64(value) {
                    self.filament_bridge_speed = v;
                }
                true
            }

            // === Extrusion ===
            "nozzle_diameter" => {
                if let Some(v) = parse_f64(value) {
                    self.nozzle_diameter = v;
                }
                true
            }
            "filament_diameter" => {
                if let Some(v) = parse_f64(value) {
                    self.filament_diameter = v;
                }
                true
            }
            // PrintConfig.hpp:1411 — print-level option read by PrintRegion::flow
            // (PrintRegion.cpp:27-28). The PrintObjectConfig keeps its own copy
            // of this key; both are fed from the same JSON value.
            "initial_layer_line_width" => {
                if let Some(v) = parse_f64(value) {
                    self.initial_layer_line_width = v;
                }
                true
            }

            // === Skirt/Brim ===
            "skirt_loops" => {
                if let Some(v) = parse_u32(value) {
                    self.skirt_loops = v;
                }
                true
            }
            "skirt_distance" => {
                if let Some(v) = parse_f64(value) {
                    self.skirt_distance = v;
                }
                true
            }

            // === Raft ===
            "raft_layers" => {
                if let Some(v) = parse_u32(value) {
                    self.raft_layers = v;
                    self.raft_enabled = v > 0;
                }
                true
            }
            "raft_expansion" => {
                if let Some(v) = parse_f64(value) {
                    self.raft_expansion = v;
                }
                true
            }
            "raft_contact_distance" => {
                if let Some(v) = parse_f64(value) {
                    self.raft_contact_distance = v;
                }
                true
            }

            // === Support ===
            "enable_support" => {
                if let Some(v) = parse_bool(value) {
                    self.support_enabled = v;
                }
                true
            }
            "support_type" => {
                if value.contains("tree") {
                    self.support_type = SupportType::Tree;
                } else if value.contains("hybrid") {
                    self.support_type = SupportType::Hybrid;
                } else {
                    self.support_type = SupportType::Normal;
                }
                true
            }
            "support_threshold_angle" => {
                if let Some(v) = parse_f64(value) {
                    self.support_threshold_angle = v;
                }
                true
            }
            "support_base_pattern_spacing" => {
                if let Some(s) = parse_f64(value) {
                    self.support_density = if s > 0.0 { 1.0 / s } else { 0.15 };
                }
                true
            }

            // === Misc ===
            "layer_change_gcode" => {
                // machine-gcode template (parent-profile key; the CLI's
                // set_deserialize path previously dropped it — R169)
                self.layer_change_gcode = value.to_string();
                true
            }
            "before_layer_change_gcode" => {
                self.before_layer_change_gcode = value.to_string();
                true
            }
            "travel_short_distance_acceleration" => {
                if let Some(v) = parse_f64(value.split(',').next().unwrap_or(value)) {
                    self.travel_short_distance_acceleration = v;
                }
                true
            }
            "z_direction_outwall_speed_continuous" => {
                if let Some(v) = parse_bool(value) {
                    self.z_direction_outwall_speed_continuous = v;
                }
                true
            }
            "spiral_mode" => {
                if let Some(v) = parse_bool(value) {
                    self.spiral_vase = v;
                }
                true
            }
            "resolution" => {
                if let Some(v) = parse_f64(value) {
                    self.resolution = v;
                }
                true
            }
            "gcode_flavor" => {
                // GCODE_FLAVOR_KEY (on unless =0): the key is read through
                // `s_keys_map_GCodeFlavor` (PrintConfig.cpp:545-559), where
                // "marlin", the value of every Bambu Lab profile, is
                // gcfMarlinLegacy and "marlin2" is gcfMarlinFirmware. The port
                // ignores the key and keeps the modern Marlin, so the G-code
                // processor does not take the extruding acceleration as the
                // travel limit (GCodeProcessor.cpp:2032-2035): travels are
                // planned at 9000 mm/s2 where C++ plans them at 10000. With the
                // key read, the processor's total over the oracle's own Benchy
                // G-code is the oracle's (2851.220 s). Opt-in until R857, with
                // the four other estimator gates: the port's G-code still
                // differs from the oracle's, so its times do, and the moved
                // `M73` lines take 2 in-order lines off Benchy arachne.
                if crate::faithful_gate("GCODE_FLAVOR_KEY") {
                    let v = value.trim().trim_matches('"');
                    let flavor = match v {
                        "marlin" => Some(GCodeFlavor::MarlinLegacy),
                        "klipper" => Some(GCodeFlavor::Klipper),
                        "reprap" => Some(GCodeFlavor::RepRapSprinter),
                        "reprapfirmware" => Some(GCodeFlavor::RepRapFirmware),
                        "repetier" => Some(GCodeFlavor::Repetier),
                        "teacup" => Some(GCodeFlavor::Teacup),
                        "makerware" => Some(GCodeFlavor::MakerWare),
                        "marlin2" => Some(GCodeFlavor::Marlin),
                        "sailfish" => Some(GCodeFlavor::Sailfish),
                        "smoothie" => Some(GCodeFlavor::Smoothie),
                        "mach3" => Some(GCodeFlavor::Mach3),
                        "machinekit" => Some(GCodeFlavor::Machinekit),
                        "no-extrusion" => Some(GCodeFlavor::NoExtrusion),
                        _ => None,
                    };
                    if let Some(f) = flavor {
                        self.gcode_flavor = f;
                    }
                }
                true
            }
            "enable_arc_fitting" => {
                if let Some(v) = parse_bool(value) {
                    self.arc_fitting_enabled = v;
                }
                true
            }
            "avoid_crossing_curled_overhangs" => {
                if let Some(v) = parse_bool(value) {
                    self.avoid_crossing_perimeters = v;
                }
                true
            }

            // === Cooling / Fan ===
            "slow_down_for_layer_cooling" => {
                if let Some(v) = parse_bool(value) {
                    self.slow_down_for_layer_cooling = v;
                }
                true
            }
            "slow_down_layer_time" => {
                if let Some(v) = parse_f64(value) {
                    self.slow_down_layer_time = v;
                }
                true
            }
            "slow_down_min_speed" => {
                if let Some(v) = parse_f64(value) {
                    self.slow_down_min_speed = v;
                }
                true
            }
            "fan_min_speed" => {
                if let Some(v) = parse_f64(value) {
                    self.fan_min_speed = v as i32;
                }
                true
            }
            "fan_max_speed" => {
                if let Some(v) = parse_f64(value) {
                    self.fan_max_speed = v as i32;
                }
                true
            }
            "fan_cooling_layer_time" => {
                if let Some(v) = parse_f64(value) {
                    self.fan_cooling_layer_time = v;
                }
                true
            }
            "close_fan_the_first_x_layers" => {
                if let Some(v) = parse_f64(value) {
                    self.close_fan_the_first_x_layers = v as usize;
                }
                true
            }
            "auxiliary_fan" => {
                if let Some(v) = parse_bool(value) {
                    self.auxiliary_fan = v;
                }
                true
            }
            // R647 — the nine keys the fan calculator reads but nothing ever set.
            "full_fan_speed_layer" => {
                if let Some(v) = parse_f64(value) {
                    self.full_fan_speed_layer = v as i32;
                }
                true
            }
            "overhang_fan_speed" => {
                if let Some(v) = parse_f64(value) {
                    self.overhang_fan_speed = v as i32;
                }
                true
            }
            "reduce_fan_stop_start_freq" => {
                if let Some(v) = parse_bool(value) {
                    self.reduce_fan_stop_start_freq = v;
                }
                true
            }
            "additional_cooling_fan_speed" => {
                if let Some(v) = parse_f64(value) {
                    self.additional_cooling_fan_speed = v as i32;
                }
                true
            }
            "first_x_layer_fan_speed" => {
                if let Some(v) = parse_f64(value) {
                    self.first_x_layer_fan_speed = v as i32;
                }
                true
            }
            "pre_start_fan_time" => {
                if let Some(v) = parse_f64(value) {
                    self.pre_start_fan_time = v as f32;
                }
                true
            }
            "no_slow_down_for_cooling_on_outwalls" => {
                if let Some(v) = parse_bool(value) {
                    self.no_slow_down_for_cooling_on_outwalls = v;
                }
                true
            }
            // PrintConfig.cpp:1585-1586 — enum_values are the two strings below.
            "cooling_slowdown_logic" => {
                self.cooling_slowdown_logic = match value {
                    "consistent_surface" => 1,
                    "uniform_cooling" => 0,
                    other => parse_f64(other).map(|v| v as i32).unwrap_or(0),
                };
                true
            }
            "cooling_perimeter_transition_distance" => {
                if let Some(v) = parse_f64(value) {
                    self.cooling_perimeter_transition_distance = v as f32;
                }
                true
            }

            // === Plate temps (handled by apply_bed_temperature, but capture here too) ===
            "cool_plate_temp" => {
                if let Some(v) = parse_f64(value) {
                    self.cool_plate_temp = v as u32;
                }
                true
            }

            // === Acceleration ===
            "initial_layer_acceleration" => {
                if let Some(v) = parse_f64(value) {
                    self.initial_layer_acceleration = v;
                }
                true
            }
            "initial_layer_travel_acceleration" => {
                if let Some(v) = parse_f64(value) {
                    self.initial_layer_travel_acceleration = v;
                }
                true
            }
            "travel_acceleration" => {
                if let Some(v) = parse_f64(value) {
                    self.travel_acceleration = v;
                }
                true
            }
            "machine_max_acceleration_extruding" => {
                if let Some(v) = parse_f64(value) {
                    self.machine_max_acceleration_extruding = v;
                }
                true
            }
            // R647: the sibling keys had no handler, so the `M204 P R T` machine
            // limit line (GCode.cpp:3601-3607) and the time estimator both read
            // struct defaults instead of the profile. Majora sets travel=9000
            // against our default 20000.
            "machine_max_acceleration_retracting" => {
                if crate::faithful_gate("MACHINE_ACCEL_KEYS") {
                    if let Some(v) = parse_f64(value) {
                        self.machine_max_acceleration_retracting = v;
                    }
                }
                true
            }
            "machine_max_acceleration_travel" => {
                if crate::faithful_gate("MACHINE_ACCEL_KEYS") {
                    if let Some(v) = parse_f64(value) {
                        self.machine_max_acceleration_travel = v;
                    }
                }
                true
            }

            // === Per-feature printing accelerations (used by GCode::_extrude's
            // "adjust acceleration" block, GCode.cpp:6393-6420). Previously these
            // keys were only handled in apply_key_value(), so the profile values
            // never reached the live PrintConfig (app_slice dispatches via
            // set_deserialize), leaving struct defaults that diverged from native.
            // sparse_infill_acceleration is a percentage of default_acceleration;
            // parse_f64 strips the trailing '%' and keeps the numeric percent. ===
            "default_acceleration" => {
                if let Some(v) = parse_f64(value) {
                    self.default_acceleration = v;
                }
                true
            }
            "outer_wall_acceleration" => {
                if let Some(v) = parse_f64(value) {
                    self.outer_wall_acceleration = v;
                }
                true
            }
            "inner_wall_acceleration" => {
                if let Some(v) = parse_f64(value) {
                    self.inner_wall_acceleration = v;
                }
                true
            }
            "top_surface_acceleration" => {
                if let Some(v) = parse_f64(value) {
                    self.top_surface_acceleration = v;
                }
                true
            }
            "sparse_infill_acceleration" => {
                if let Some(v) = parse_f64(value) {
                    self.sparse_infill_acceleration = v;
                }
                true
            }

            // === Wipe / prime tower (main.cpp _make_wipe_tower inputs) ===
            // These are consumed only by the psWipeTower phase, which is
            // gated on `enable_prime_tower && multicolour`; single-material
            // and tower-disabled jobs read but do not act on them.
            "enable_prime_tower" => {
                if let Some(v) = parse_bool(value) {
                    self.enable_prime_tower = v;
                }
                true
            }
            "prime_tower_width" => {
                if let Some(v) = parse_f64(value) {
                    self.prime_tower_width = v;
                }
                true
            }
            "prime_tower_lift_speed" => {
                if let Some(v) = parse_f64(value) {
                    self.prime_tower_lift_speed = v;
                }
                true
            }
            "prime_tower_brim_width" => {
                if let Some(v) = parse_f64(value) {
                    self.prime_tower_brim_width = v;
                }
                true
            }
            "scan_first_layer" => {
                if let Some(v) = parse_bool(value) {
                    self.scan_first_layer = v;
                }
                true
            }
            "prime_tower_wipe_speed" => {
                if let Some(v) = parse_f64(value) {
                    self.prime_tower_wipe_speed = v;
                }
                true
            }
            "prime_tower_wipe_distance" => {
                if let Some(v) = parse_f64(value) {
                    self.prime_tower_wipe_distance = v;
                }
                true
            }
            // R499: this key had NO field and NO arm at all, though it is in
            // preset.rs's key list and generator.rs's defaults, so our
            // `use_gap_wall` was permanently false and the tower emitted none of
            // the per-toolchange ironing geometry.
            "prime_tower_max_speed" => {
                if let Some(v) = parse_f64(value) {
                    self.prime_tower_max_speed = v;
                }
                true
            }
            "prime_tower_skip_points" => {
                if let Some(v) = parse_bool(value) {
                    self.prime_tower_skip_points = v;
                }
                true
            }
            // R509: fourth instance of the config-key pattern — present in
            // `apply_key_value` but not here, so it never reached PrintConfig.
            // C++ derives `WipeTower::m_enable_timelapse_print` from it
            // (WipeTower.cpp:1742, `timelapse_type == tlSmooth` with tlSmooth = 1),
            // and that flag forces every plan layer's tower depth to the full
            // tower depth.
            "timelapse_type" => {
                if let Some(v) = parse_f64(value) {
                    self.timelapse_type = v as u32;
                }
                true
            }
            "wipe_tower_x" => {
                if let Some(v) = parse_f64(value) {
                    self.wipe_tower_x = v;
                }
                true
            }
            "wipe_tower_y" => {
                if let Some(v) = parse_f64(value) {
                    self.wipe_tower_y = v;
                }
                true
            }
            // Flush-into-object routing (C++ WipingExtrusions::is_overriddable):
            // when set, part of a tool change's purge is absorbed by the object's
            // own extrusions instead of the wipe tower.
            "flush_into_infill" => {
                if let Some(v) = parse_bool(value) {
                    self.flush_into_infill = v;
                }
                true
            }
            "flush_into_objects" => {
                if let Some(v) = parse_bool(value) {
                    self.flush_into_objects = v;
                }
                true
            }
            "wipe_distance" => {
                // R807: BBS filament key (GCode.cpp:380 wipe_distance.get_at);
                // previously dropped by the vetted fallback below, leaving the
                // writer at its 1.0 mm default against the profile's 2.0.
                if let Some(v) = value
                    .split(',')
                    .next()
                    .and_then(|t| t.trim().parse::<f64>().ok())
                {
                    self.wipe_distance_profile = Some(v);
                }
                true
            }
            "flush_into_support" => {
                if let Some(v) = parse_bool(value) {
                    self.flush_into_support = v;
                }
                true
            }

            // GCodeProcessor.cpp:2030-2036 — the machine envelope the processor
            // takes from the config (MACHINE_LIMITS): the first (Normal) value of
            // each per-extruder, per-mode array. =0 keeps the defaults.
            "machine_max_acceleration_x" => {
                if crate::faithful_gate("MACHINE_LIMITS") {
                    if let Some(v) = value.split(',').next().and_then(parse_f64) {
                        self.machine_max_acceleration_x = v;
                    }
                }
                true
            }
            "machine_max_acceleration_y" => {
                if crate::faithful_gate("MACHINE_LIMITS") {
                    if let Some(v) = value.split(',').next().and_then(parse_f64) {
                        self.machine_max_acceleration_y = v;
                    }
                }
                true
            }
            "machine_max_acceleration_z" => {
                if crate::faithful_gate("MACHINE_LIMITS") {
                    if let Some(v) = value.split(',').next().and_then(parse_f64) {
                        self.machine_max_acceleration_z = v;
                    }
                }
                true
            }
            "machine_max_acceleration_e" => {
                if crate::faithful_gate("MACHINE_LIMITS") {
                    if let Some(v) = value.split(',').next().and_then(parse_f64) {
                        self.machine_max_acceleration_e = v;
                    }
                }
                true
            }
            "machine_max_speed_x" => {
                if crate::faithful_gate("MACHINE_LIMITS") {
                    if let Some(v) = value.split(',').next().and_then(parse_f64) {
                        self.machine_max_speed_x = v;
                    }
                }
                true
            }
            "machine_max_speed_y" => {
                if crate::faithful_gate("MACHINE_LIMITS") {
                    if let Some(v) = value.split(',').next().and_then(parse_f64) {
                        self.machine_max_speed_y = v;
                    }
                }
                true
            }
            "machine_max_speed_z" => {
                if crate::faithful_gate("MACHINE_LIMITS") {
                    if let Some(v) = value.split(',').next().and_then(parse_f64) {
                        self.machine_max_speed_z = v;
                    }
                }
                true
            }
            "machine_max_speed_e" => {
                if crate::faithful_gate("MACHINE_LIMITS") {
                    if let Some(v) = value.split(',').next().and_then(parse_f64) {
                        self.machine_max_speed_e = v;
                    }
                }
                true
            }
            "machine_max_jerk_x" => {
                if crate::faithful_gate("MACHINE_LIMITS") {
                    if let Some(v) = value.split(',').next().and_then(parse_f64) {
                        self.machine_max_jerk_x = v;
                    }
                }
                true
            }
            "machine_max_jerk_y" => {
                if crate::faithful_gate("MACHINE_LIMITS") {
                    if let Some(v) = value.split(',').next().and_then(parse_f64) {
                        self.machine_max_jerk_y = v;
                    }
                }
                true
            }
            "machine_max_jerk_z" => {
                if crate::faithful_gate("MACHINE_LIMITS") {
                    if let Some(v) = value.split(',').next().and_then(parse_f64) {
                        self.machine_max_jerk_z = v;
                    }
                }
                true
            }
            "machine_max_jerk_e" => {
                if crate::faithful_gate("MACHINE_LIMITS") {
                    if let Some(v) = value.split(',').next().and_then(parse_f64) {
                        self.machine_max_jerk_e = v;
                    }
                }
                true
            }
            "machine_min_extruding_rate" => {
                if crate::faithful_gate("MACHINE_LIMITS") {
                    if let Some(v) = value.split(',').next().and_then(parse_f64) {
                        self.machine_min_extruding_rate = v;
                    }
                }
                true
            }
            "machine_min_travel_rate" => {
                if crate::faithful_gate("MACHINE_LIMITS") {
                    if let Some(v) = value.split(',').next().and_then(parse_f64) {
                        self.machine_min_travel_rate = v;
                    }
                }
                true
            }
            // GCodeProcessor.cpp:2054 — read by the G-code processor (PROCESS_G4_G29).
            "machine_prepare_compensation_time" => {
                if let Some(v) = parse_f64(value) {
                    self.machine_prepare_compensation_time = v;
                }
                true
            }
            // GCodeProcessor.cpp:2002, 2045-2053 — read by the G-code processor
            // (PROCESS_FILAMENT_CHANGE).
            "machine_load_filament_time" => {
                if let Some(v) = parse_f64(value) {
                    self.machine_load_filament_time = v;
                }
                true
            }
            "machine_unload_filament_time" => {
                if let Some(v) = parse_f64(value) {
                    self.machine_unload_filament_time = v;
                }
                true
            }
            "machine_switch_extruder_time" => {
                if let Some(v) = parse_f64(value) {
                    self.machine_switch_extruder_time = v;
                }
                true
            }
            "machine_hotend_change_time" => {
                if let Some(v) = parse_f64(value) {
                    self.machine_hotend_change_time = v;
                }
                true
            }
            "handle_hotend_as_extruder" => {
                self.handle_hotend_as_extruder = parse_bool(value).unwrap_or(false);
                true
            }
            k if is_ams_filament_time(k) && crate::faithful_gate("PROCESSOR_AMS_TIMES") => {
                use crate::config::{ConfigOption, ConfigOptionFloat};
                let mut option = ConfigOptionFloat::new();
                if matches!(option.deserialize(value, false), Ok(true)) {
                    self.ams_filament_times.insert(k.to_owned(), option.value);
                }
                true
            }
            "default_ams_type" => {
                if let Some(v) = parse_f64(value) {
                    self.default_ams_type = v as i32;
                }
                true
            }
            // PrintConfig.cpp:6362-6369, 6395-6403 (`support_filament`, `support_interface_filament`, coInt, default
            // 0, min 0): the settings' support filaments reach the live configuration, as the pin's
            // `load_from_json` sets them (Config.cpp:885-1243). Gate PRINT_CONFIG_SUPPORT_FILAMENT_PIN (faithful,
            // R949); off, the live configuration keeps 0 (support printed with the current filament).
            "support_filament" | "support_interface_filament" if crate::faithful_gate("PRINT_CONFIG_SUPPORT_FILAMENT_PIN") => {
                self.apply_key_value(key, value);
                true
            }
            _ => {
                // ZSMOOTH_FAITHFUL: delegate a VETTED set of keys to
                // apply_key_value (R170 audit: the two config-application fns
                // have divergent coverage; a blanket fallback measured +119 —
                // land keys selectively against the oracle).
                if crate::faithful_gate("ZSMOOTH_FAITHFUL")
                    && matches!(
                        key,
                        "initial_layer_infill_speed"
                            | "filament_max_volumetric_speed"
                            | "vertical_shell_speed"
                            | "reduce_fan_stop_start_freq"
                            | "retraction_minimum_travel"
                            | "no_slow_down_for_cooling_on_outwalls"
                    )
                {
                    self.apply_key_value(key, value)
                } else {
                    false
                }
            }
        }
    }
}

impl PrintObjectConfig {
    /// `enable_circle_compensation` (ConfigOptionBool::deserialize, Config.hpp:1866-1872: "1" or "0",
    /// anything else fails and keeps the value) and `circle_compensation_manual_offset`
    /// (ConfigOptionFloat::deserialize, Config.hpp:842-848: `iss >> value`) of PrintConfig.hpp:1109-1110.
    /// Returns false for any other key.
    pub fn set_deserialize_circle_compensation(&mut self, key: &str, value: &str) -> bool {
        use crate::config::ConfigOption as _;
        match key {
            "enable_circle_compensation" => {
                let mut opt = crate::config::ConfigOptionBool { value: self.enable_circle_compensation };
                let _ = opt.deserialize(value, false);
                self.enable_circle_compensation = opt.value;
                true
            }
            "circle_compensation_manual_offset" => {
                let mut opt = crate::config::ConfigOptionFloat { value: self.circle_compensation_manual_offset };
                let _ = opt.deserialize(value, false);
                self.circle_compensation_manual_offset = opt.value;
                true
            }
            _ => false,
        }
    }
}

impl PrintObjectConfig {
    /// Apply a key-value pair from BambuStudio project_settings JSON.
    /// Returns true if the key was recognized and applied.
    pub fn set_deserialize(&mut self, key: &str, value: &str) -> bool {
        match key {
            // === Layer Heights ===
            "layer_height" => {
                if let Some(v) = parse_f64(value) {
                    self.layer_height = v;
                }
                true
            }
            "initial_layer_print_height" => {
                if let Some(v) = parse_f64(value) {
                    self.first_layer_height = v;
                }
                true
            }

            // === Perimeters ===
            "wall_loops" => {
                if let Some(v) = parse_u32(value) {
                    self.perimeters = v;
                }
                true
            }
            "top_shell_layers" => {
                if let Some(v) = parse_u32(value) {
                    self.top_solid_layers = v;
                }
                true
            }
            "bottom_shell_layers" => {
                if let Some(v) = parse_u32(value) {
                    self.bottom_solid_layers = v;
                }
                true
            }

            // === Infill ===
            "sparse_infill_density" => {
                if let Some(v) = parse_pct(value) {
                    self.fill_density = v;
                }
                true
            }
            "sparse_infill_pattern" => {
                self.fill_pattern = match value {
                    "grid" => InfillPattern::Grid,
                    "line" | "rectilinear" => InfillPattern::Rectilinear,
                    "gyroid" => InfillPattern::Gyroid,
                    "honeycomb" => InfillPattern::Honeycomb,
                    "concentric" => InfillPattern::Concentric,
                    "cubic" => InfillPattern::Cubic,
                    "lightning" => InfillPattern::Lightning,
                    "triangles" => InfillPattern::Triangles,
                    "adaptivecubic" => InfillPattern::AdaptiveCubic,
                    _ => self.fill_pattern,
                };
                true
            }
            "monotonic_travel_into_wall" => {
                if let Some(v) = parse_pct(value) {
                    self.monotonic_travel_into_wall = v;
                }
                true
            }
            "infill_wall_overlap" => {
                if let Some(v) = parse_pct(value) {
                    self.infill_wall_overlap = v;
                }
                true
            }
            "infill_direction" => {
                if let Some(v) = parse_f64(value) {
                    self.infill_angle = v;
                }
                true
            }
            "minimum_sparse_infill_area" => {
                if let Some(v) = parse_f64(value) {
                    self.minimum_sparse_infill_area = v;
                }
                true
            }
            "detect_narrow_internal_solid_infill" => {
                if let Some(v) = parse_bool(value) {
                    self.detect_narrow_internal_solid_infill = v;
                }
                true
            }
            // R480: this key was handled only by `apply_key_value`, never by
            // `set_deserialize`, which is the entry point the settings/3MF loader
            // uses -- so it stayed at its `false` default no matter what the profile
            // said. `FillFloatingConcentric::resplit_order_loops`
            // (FillFloatingConcentric.cpp:691-702) reads it as
            // `force_no_detect = !detect_floating_vertical_shell || is_self_intersect`,
            // so detect_floating_line was forced OFF for all 8,626 of Majora's beads
            // and no bead was ever split into floating / supported spans.
            "detect_floating_vertical_shell" => {
                if let Some(v) = parse_bool(value) {
                    self.detect_floating_vertical_shell = v;
                }
                true
            }

            // === Line Widths ===
            "line_width" => {
                if let Some(v) = parse_f64(value) {
                    self.line_width = v;
                }
                true
            }
            "initial_layer_line_width" => {
                if let Some(v) = parse_f64(value) {
                    self.initial_layer_line_width = v;
                }
                true
            }
            "outer_wall_line_width" => {
                if let Some(v) = parse_f64(value) {
                    self.outer_wall_line_width = v;
                }
                true
            }
            "inner_wall_line_width" => {
                if let Some(v) = parse_f64(value) {
                    self.inner_wall_line_width = v;
                }
                true
            }
            "sparse_infill_line_width" => {
                if let Some(v) = parse_f64(value) {
                    self.sparse_infill_line_width = v;
                }
                true
            }
            "internal_solid_infill_line_width" => {
                if let Some(v) = parse_f64(value) {
                    self.solid_infill_line_width = v;
                }
                true
            }
            "top_surface_line_width" => {
                if let Some(v) = parse_f64(value) {
                    self.top_surface_line_width = v;
                }
                true
            }

            // === Speeds ===
            "inner_wall_speed" => {
                if let Some(v) = parse_f64(value) {
                    self.perimeter_speed = v;
                }
                true
            }
            "outer_wall_speed" => {
                if let Some(v) = parse_f64(value) {
                    self.external_perimeter_speed = v;
                }
                true
            }
            "sparse_infill_speed" => {
                if let Some(v) = parse_f64(value) {
                    self.infill_speed = v;
                }
                true
            }
            "internal_solid_infill_speed" => {
                if let Some(v) = parse_f64(value) {
                    self.solid_infill_speed = v;
                }
                true
            }
            "top_surface_speed" => {
                if let Some(v) = parse_f64(value) {
                    self.top_solid_infill_speed = v;
                }
                true
            }
            "bridge_speed" => {
                if let Some(v) = parse_f64(value) {
                    self.bridge_speed = v;
                }
                true
            }
            "gap_infill_speed" => {
                if let Some(v) = parse_f64(value) {
                    self.gap_fill_speed = v;
                }
                true
            }

            // === Overhang Speed ===
            // GCode.cpp:5348-5366 overhang_speed_key_map; values may be mm/s or
            // a `%` of the normal wall speed (resolved in the exporter via
            // get_abs_value). We keep the raw value (with `%` stripped) and the
            // exporter applies the percent semantics.
            "enable_overhang_speed" => {
                if let Some(v) = parse_bool(value) {
                    self.enable_overhang_speed = v;
                }
                true
            }
            "enable_overhang_bridge_fan" => {
                // per-filament list "1,1,1,1,1" — first element
                if let Some(v) = parse_bool(value.split(',').next().unwrap_or(value)) {
                    self.enable_overhang_bridge_fan = v;
                }
                true
            }
            "overhang_fan_threshold" => {
                // enum strings (PrintConfig.cpp:1200-1205); may be per-filament list
                let first = value.split(',').next().unwrap_or(value).trim();
                self.overhang_fan_threshold = match first {
                    "0%" => 0,
                    "10%" => 1,
                    "25%" => 2,
                    "50%" => 3,
                    "75%" => 4,
                    "95%" => 5,
                    _ => self.overhang_fan_threshold,
                };
                true
            }
            "overhang_1_4_speed" => {
                if let Some(v) = parse_f64(value) {
                    self.overhang_1_4_speed = v;
                }
                true
            }
            "overhang_2_4_speed" => {
                if let Some(v) = parse_f64(value) {
                    self.overhang_2_4_speed = v;
                }
                true
            }
            "overhang_3_4_speed" => {
                if let Some(v) = parse_f64(value) {
                    self.overhang_3_4_speed = v;
                }
                true
            }
            "overhang_4_4_speed" => {
                if let Some(v) = parse_f64(value) {
                    self.overhang_4_4_speed = v;
                }
                true
            }
            "overhang_totally_speed" => {
                if let Some(v) = parse_f64(value) {
                    self.overhang_totally_speed = v;
                }
                true
            }
            "smooth_speed_discontinuity_area" => {
                if let Some(v) = parse_bool(value) {
                    self.smooth_speed_discontinuity_area = v;
                }
                true
            }
            "smooth_coefficient" => {
                if let Some(v) = parse_f64(value) {
                    self.smooth_coefficient = v;
                }
                true
            }

            // === Perimeter Options ===
            "detect_thin_wall" => {
                if let Some(v) = parse_bool(value) {
                    self.thin_walls = v;
                }
                true
            }
            "detect_overhang_wall" => {
                if let Some(v) = parse_bool(value) {
                    self.overhangs = v;
                }
                true
            }
            "only_one_wall_first_layer" => {
                if let Some(v) = parse_bool(value) {
                    self.only_one_wall_first_layer = v;
                }
                true
            }
            "top_one_wall_type" => {
                self.top_one_wall_type = match value {
                    "all top" => TopOneWallType::AllTop,
                    "topmost" => TopOneWallType::TopMost,
                    _ => TopOneWallType::None,
                };
                true
            }

            // === Quality ===
            "slice_closing_radius" => {
                if let Some(v) = parse_f64(value) {
                    self.slice_closing_radius = v;
                }
                true
            }
            "xy_hole_compensation" => {
                if let Some(v) = parse_f64(value) {
                    self.xy_size_compensation = v;
                }
                true
            }
            // PrintConfig.hpp:1109-1110, deserialized as the pin's ConfigOptionBool (Config.hpp:1866-1872)
            // and ConfigOptionFloat (Config.hpp:842-848).
            "enable_circle_compensation" | "circle_compensation_manual_offset" => {
                self.set_deserialize_circle_compensation(key, value)
            }
            "elefant_foot_compensation" => {
                if let Some(v) = parse_f64(value) {
                    self.elephant_foot_compensation = v;
                }
                true
            }

            // === Flow ===
            "initial_layer_flow_ratio" => {
                if let Some(v) = parse_f64(value) {
                    self.initial_layer_flow_ratio = v;
                }
                true
            }
            "top_solid_infill_flow_ratio" => {
                if let Some(v) = parse_f64(value) {
                    self.top_solid_infill_flow_ratio = v;
                }
                true
            }
            "print_flow_ratio" => {
                if let Some(v) = parse_f64(value) {
                    self.print_flow_ratio = v;
                }
                true
            }

            // === Seam ===
            "seam_position" => {
                self.seam_position = match value {
                    "aligned" => SeamPosition::Aligned,
                    "random" => SeamPosition::Random,
                    "back" | "rear" => SeamPosition::Rear,
                    "nearest" => SeamPosition::Nearest,
                    _ => self.seam_position,
                };
                true
            }
            // PrintConfig.cpp:4650 — coBool, default false.
            "seam_placement_away_from_overhangs" => {
                if let Some(v) = parse_bool(value) {
                    self.seam_placement_away_from_overhangs = v;
                }
                true
            }

            // === Fuzzy Skin ===
            "fuzzy_skin" => {
                self.fuzzy_skin = value == "1"
                    || value == "true"
                    || value == "external"
                    || value == "allwalls"
                    || value == "all";
                true
            }
            "fuzzy_skin_thickness" => {
                if let Some(v) = parse_f64(value) {
                    self.fuzzy_skin_thickness = v;
                }
                true
            }
            "fuzzy_skin_point_distance" | "fuzzy_skin_point_dist" => {
                if let Some(v) = parse_f64(value) {
                    self.fuzzy_skin_point_distance = v;
                }
                true
            }

            // === Wipe ===
            "wipe" => {
                if let Some(v) = parse_bool(value) {
                    self.wipe_enabled = v;
                }
                true
            }
            "wipe_distance" => {
                if let Some(v) = parse_f64(value) {
                    self.wipe_distance = v;
                }
                true
            }

            // === Arachne ===
            "wall_generator" => {
                self.perimeter_mode = match value {
                    "arachne" => PerimeterMode::Arachne,
                    _ => PerimeterMode::Classic,
                };
                true
            }
            "min_bead_width" => {
                // R706 — coPercent: store the percent number (see parse_percent_number).
                if let Some(v) = parse_percent_number(value) {
                    self.arachne_min_bead_width = v;
                }
                true
            }
            "min_feature_size" => {
                // R706 — coPercent: store the percent number (see parse_percent_number).
                if let Some(v) = parse_percent_number(value) {
                    self.arachne_min_feature_size = v;
                }
                true
            }
            "wall_transition_length" => {
                // R706 — coPercent: store the percent number (see parse_percent_number).
                if let Some(v) = parse_percent_number(value) {
                    self.arachne_wall_transition_length = v;
                }
                true
            }

            // === Misc ===
            "spiral_mode" => {
                if let Some(v) = parse_bool(value) {
                    self.spiral_vase = v;
                }
                true
            }

            // === Raft (object-level) ===
            "raft_layers" => {
                if let Some(v) = parse_u32(value) {
                    self.raft_layers = v;
                }
                true
            }
            "raft_expansion" => {
                if let Some(v) = parse_f64(value) {
                    self.raft_expansion = v;
                }
                true
            }
            "raft_contact_distance" => {
                if let Some(v) = parse_f64(value) {
                    self.raft_contact_distance = v;
                }
                true
            }

            // === Support (object-level) ===
            "enable_support" => {
                if let Some(v) = parse_bool(value) {
                    self.enable_support = v;
                }
                true
            }
            "support_type" => {
                if value.contains("tree") {
                    self.support_type = SupportType::Tree;
                } else if value.contains("hybrid") {
                    self.support_type = SupportType::Hybrid;
                } else {
                    self.support_type = SupportType::Normal;
                }
                true
            }
            "enforce_support_layers" => {
                if let Some(v) = parse_u32(value) {
                    self.enforce_support_layers = v;
                }
                true
            }
            "support_threshold_angle" => {
                if let Some(v) = parse_f64(value) {
                    self.support_threshold_angle = v;
                }
                true
            }
            "support_on_build_plate_only" => {
                if let Some(v) = parse_bool(value) {
                    self.support_on_build_plate_only = v;
                }
                true
            }
            "support_line_width" => {
                if let Some(v) = parse_f64(value) {
                    self.support_line_width = v;
                }
                true
            }
            "support_base_pattern_spacing" => {
                if let Some(v) = parse_f64(value) {
                    self.support_base_pattern_spacing = v;
                }
                true
            }
            "support_interface_top_layers" => {
                if let Some(v) = parse_u32(value) {
                    self.support_interface_top_layers = v;
                }
                true
            }
            "support_interface_bottom_layers" => {
                if let Some(v) = parse_i32(value) {
                    self.support_interface_bottom_layers = v;
                }
                true
            }
            "support_interface_spacing" => {
                if let Some(v) = parse_f64(value) {
                    self.support_interface_spacing = v;
                }
                true
            }
            "support_top_z_distance" => {
                if let Some(v) = parse_f64(value) {
                    self.support_top_z_distance = v;
                }
                true
            }
            "support_bottom_z_distance" => {
                if let Some(v) = parse_f64(value) {
                    self.support_bottom_z_distance = v;
                }
                true
            }
            "support_object_xy_distance" => {
                if let Some(v) = parse_f64(value) {
                    self.support_object_xy_distance = v;
                }
                true
            }
            "support_expansion" => {
                if let Some(v) = parse_f64(value) {
                    self.support_expansion = v;
                }
                true
            }
            "support_angle" => {
                if let Some(v) = parse_f64(value) {
                    self.support_angle = v;
                }
                true
            }
            "support_object_first_layer_gap" => {
                if let Some(v) = parse_f64(value) {
                    self.support_object_first_layer_gap = v;
                }
                true
            }
            "enable_support_ironing" => {
                if let Some(v) = parse_bool(value) {
                    self.enable_support_ironing = v;
                }
                true
            }
            "support_ironing_pattern" => {
                self.support_ironing_pattern = InfillPattern::from_str_bambu(value);
                true
            }
            "support_ironing_flow" => {
                // coPercent — stored as fraction 0..1
                if let Some(v) = parse_pct(value) {
                    self.support_ironing_flow = v;
                }
                true
            }
            "support_ironing_spacing" => {
                if let Some(v) = parse_f64(value) {
                    self.support_ironing_spacing = v;
                }
                true
            }
            "support_ironing_inset" => {
                if let Some(v) = parse_f64(value) {
                    self.support_ironing_inset = v;
                }
                true
            }
            "support_ironing_direction" => {
                if let Some(v) = parse_f64(value) {
                    self.support_ironing_direction = v;
                }
                true
            }
            "support_ironing_speed" => {
                if let Some(v) = parse_f64(value) {
                    self.support_ironing_speed = v;
                }
                true
            }
            // R934: `ironing_speed` (PrintConfig.hpp, a region option the pin's GCode reads
            // through m_config, GCode.cpp:7749); the export reads this struct's copy.
            "ironing_speed" => {
                if let Some(v) = parse_f64(value) {
                    self.ironing_speed = v;
                }
                true
            }

            // === Interlocking (PrintConfig.hpp:1008-1013) ===
            "interlocking_beam" => {
                if let Some(v) = parse_bool(value) {
                    self.interlocking_beam = v;
                }
                true
            }
            "interlocking_beam_width" => {
                if let Some(v) = parse_f64(value) {
                    self.interlocking_beam_width = v;
                }
                true
            }
            "interlocking_orientation" => {
                if let Some(v) = parse_f64(value) {
                    self.interlocking_orientation = v;
                }
                true
            }
            "interlocking_beam_layer_count" => {
                if let Ok(v) = value.trim().parse::<i32>() {
                    self.interlocking_beam_layer_count = v;
                }
                true
            }
            "interlocking_depth" => {
                if let Ok(v) = value.trim().parse::<i32>() {
                    self.interlocking_depth = v;
                }
                true
            }
            "interlocking_boundary_avoidance" => {
                if let Ok(v) = value.trim().parse::<i32>() {
                    self.interlocking_boundary_avoidance = v;
                }
                true
            }

            _ => {
                // ZSMOOTH_FAITHFUL: delegate a VETTED set of keys to
                // apply_key_value (R170 audit: the two config-application fns
                // have divergent coverage; a blanket fallback measured +119 —
                // land keys selectively against the oracle).
                if crate::faithful_gate("ZSMOOTH_FAITHFUL")
                    && matches!(
                        key,
                        "initial_layer_infill_speed"
                            | "filament_max_volumetric_speed"
                            | "vertical_shell_speed"
                            | "reduce_fan_stop_start_freq"
                            | "retraction_minimum_travel"
                            | "no_slow_down_for_cooling_on_outwalls"
                    )
                {
                    self.apply_key_value(key, value)
                } else {
                    false
                }
            }
        }
    }
}

